using System.Globalization;

namespace Educator.Core.Exercises;

/// <summary>
/// One addition generated by <see cref="AdditionGenerator"/> (lot 0 proof of concept, SUB006007).
/// The expected answer never leaves the host before the child has answered.
/// </summary>
public sealed record AdditionExercise(Guid Id, int Left, int Right)
{
    public int ExpectedAnswer => Left + Right;

    /// <summary>Written form shown on screen, e.g. <c>3 + 4</c>.</summary>
    public string Statement => string.Create(CultureInfo.InvariantCulture, $"{Left} + {Right}");

    /// <summary>Sentence read aloud by the speech synthesizer.</summary>
    public string SpokenStatement => string.Create(CultureInfo.InvariantCulture, $"Combien font {Left} plus {Right} ?");

    public AnswerResult Check(int answer) => new(answer == ExpectedAnswer, ExpectedAnswer);
}

/// <summary>Outcome of an answer: whether it is correct and the expected value.</summary>
public sealed record AnswerResult(bool IsCorrect, int ExpectedAnswer);
